 private String every(int minutes){if(!fr)return ScheduleConfig.label(minutes);if(minutes==60)return getString(R.string.every_hour);return minutes%60==0?getString(R.string.every_hours,minutes/60):getString(R.string.every_minutes,minutes);}
 private String look(int mode){return fr?getResources().getStringArray(R.array.appearance_modes)[mode]:Appearance.label(mode);}
 private String daySum(int d){if(!fr)return WeeklySchedule.daySummary(cfg,d);try{JSONObject row=WeeklySchedule.rules(cfg).optJSONObject(Integer.toString(d));if(row==null||row.length()==0)return getString(R.string.usual_restaurants);StringBuilder x=new StringBuilder();for(int m=1;m<=3;m++){JSONObject rule=row.optJSONObject(Integer.toString(m));if(rule!=null){if(x.length()>0)x.append(" · ");x.append(meal(m)).append(": ").append(Boolean.TRUE.equals(rule.opt("skip"))?getString(R.string.meal_unconfigured):rule.optString("name","#"+rule.optLong("id")));}}return x.toString();}catch(Exception e){return getString(R.string.invalid_schedule);}}
