 private Button button(LinearLayout p,String label,boolean primary,Runnable click){return make(p,label,primary?PRIMARY:PLAIN,click);}
 private Button nav(LinearLayout p,String label,Runnable click){return make(p,label,NAV,click);}
 /** PRIMARY = one filled action per screen, PLAIN = outlined secondary action, NAV = row that opens another screen (chevron), DANGER = destructive. Heights are minimums so large font scales never clip. */
 private Button make(LinearLayout p,String label,int kind,Runnable click){
  Button b=new Button(this);b.setText(label);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(kind==PRIMARY?Color.WHITE:kind==DANGER?palette.danger:blue);b.setStateListAnimator(null);b.setElevation(0);b.setMinHeight(dp(50));b.setMinimumHeight(dp(50));b.setPadding(dp(kind==NAV?3:12),dp(8),dp(kind==NAV?3:12),dp(8));
  Drawable shape=kind==PRIMARY?bg(palette.primary,12):kind==DANGER?outline(palette.surface,palette.danger,12):kind==PLAIN?outline(palette.surface,palette.line,12):bg(palette.surface,12);
  b.setBackground(new RippleDrawable(ColorStateList.valueOf(Color.argb(25,128,128,128)),shape,null));
  if(kind==PRIMARY||kind==DANGER)b.setTypeface(null,Typeface.BOLD);
  if(kind==NAV){b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setCompoundDrawablesRelativeWithIntrinsicBounds(null,null,new ChevronDrawable(getResources().getDisplayMetrics().density,palette.chevron).right(fr),null);}
  LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.setMargins(0,dp(4),0,dp(4));p.addView(b,l);actions.add(b);b.setOnClickListener(v->click.run());return b;
 }
