 private String concise(String s){if(s==null||s.isEmpty()||s.equals(Vault.NO_STATUS))return getString(R.string.concise_1);Matcher m=Pattern.compile("S[0-9]{2}").matcher(s);String stage=m.find()?" · "+m.group():"";if(s.contains("401"))return getString(R.string.concise_2)+stage+")";if(s.contains("403"))return getString(R.string.concise_3)+stage+")";String line=s.split("\\n",2)[0];return line.length()>160?line.substring(0,157)+"…":line;}
 private void message(String s){say(s,false);}
 /** Errors stay on screen next to the action that caused them until the next action; they are never a transient toast. */
 private void fail(String s){say(s==null||s.isEmpty()?getString(R.string.fail_1):s,true);}
 private void say(String s,boolean error){
  lastDetail=s;status.setText(concise(s));
  if(mode==2){for(TextView t:pageNote)t.setVisibility(View.GONE);wizardMessage.setText(error?"":s);if(error){TextView t=pageNote[step];t.setText(concise(s));t.setVisibility(View.VISIBLE);}return;}
  notice.setText(concise(s));notice.setTextColor(error?palette.danger:ink);notice.setBackground(error?bg(palette.dangerBg,13):outline(palette.surface,palette.line,13));notice.setContentDescription(concise(s)+getString(R.string.say_1));notice.setVisibility(View.VISIBLE);
 }
 private boolean free(){if(busy||Runner.LOCK.isLocked()){message(getString(R.string.go_back_1));return false;}return true;}
 interface Task<T>{T run()throws Exception;}interface Done<T>{void run(T x)throws Exception;}
 private void lockUi(boolean value){busy=value;if(!value&&bookLoading){bookLoading=false;renderBookings();}progress.setVisibility(value?View.VISIBLE:View.GONE);busyBar.setVisibility(value?View.VISIBLE:View.GONE);float a=value?.45f:1f;for(Button b:actions){b.setEnabled(!value);b.setAlpha(a);}tabs.setAlpha(a);student.setAlpha(a);password.setAlpha(a);autoSwitch.setEnabled(!value);student.setEnabled(!value);password.setEnabled(!value);for(int m=1;m<=3;m++)meals[m].setEnabled(!value);intervalInput.enabled(!value);}
 private <T> void async(String label,Task<T> work,Done<T> then){if(!free())return;lockUi(true);message(label);notice.setVisibility(View.GONE);busyText.setText(label);executor.execute(()->{try{T result=work.run();runOnUiThread(()->{if(isDestroyed())return;lockUi(false);try{then.run(result);}catch(Exception e){fail(Runner.safe(e));}});}catch(Exception e){String safe=Runner.safe(e);vault.status(safe);runOnUiThread(()->{if(isDestroyed())return;lockUi(false);fail(safe);});}});}
 private void connect(){if(!free())return;try{JSONObject old=vault.account();String id=student.getText().toString().trim(),pass=password.getText().toString();if(pass.isEmpty())pass=old.optString("password");if(id.isEmpty()||pass.isEmpty()){fail(getString(R.string.connect_1));return;}boolean changed=!id.equals(old.optString("student"))||!pass.equals(old.optString("password"));JSONObject next=changed?new JSONObject().put("student",id).put("password",pass).put("meal_schema",2):new JSONObject(old.toString());if(changed){Automation.disengage(this,vault,true);vault.accountVerified(false);depots=new JSONArray();draftMeals=new JSONObject();draftMinutes=-1;}vault.write("account",next);cfg=next;password.setText("");preview=null;update();async(getString(R.string.connect_2),()->Runner.inspect(next),r->{vault.accountVerified(true);depots=r.depots;fillMeals();intervalInput.set(vault.intervalMinutes());setStep(1);message(getString(R.string.connect_3));});}catch(Exception e){fail(Runner.safe(e));}}
 private void fillMeals()throws Exception{for(int m=1;m<=3;m++){choices[m]=AccountSettings.options(depots,m);List<String> names=new ArrayList<>();names.add(choices[m].isEmpty()?getString(R.string.fill_meals_1):getString(R.string.screen_51));int selected=0;for(int i=0;i<choices[m].size();i++){JSONObject d=choices[m].get(i);names.add(Engine.name(d));if(d.getLong("id")==draftMeals.optLong(AccountSettings.IDS[m],cfg.optLong(AccountSettings.IDS[m])))selected=i+1;}meals[m].setItems(names);meals[m].setSelection(selected);}}
 private void reloadRestaurants(){if(!vault.accountVerified()){setStep(0);message(getString(R.string.reload_restaurants_1));return;}JSONObject c=cfg;async(getString(R.string.reload_restaurants_2),()->Runner.inspect(c),r->{depots=r.depots;fillMeals();message(getString(R.string.reload_restaurants_3));});}
 private void saveMeals(){if(!free())return;if(storeMeals())loadReview();}
 /** Saves the three usual restaurants and the interval shown in step 2. Returns false (with a message) when a meal has no restaurant yet. */
 private boolean storeMeals(){try{JSONObject[] selected=new JSONObject[4];for(int m=1;m<=3;m++){int i=meals[m].getSelectedItemPosition()-1;selected[m]=(i>=0&&i<choices[m].size())?choices[m].get(i):null;}int minutes=intervalInput.get();JSONObject next=AccountSettings.select(cfg,selected);boolean changed=!AccountSettings.sameChoices(cfg,next);if(changed){Automation.disengage(this,vault,true);}vault.write("account",next);cfg=next;draftMeals=new JSONObject();draftMinutes=-1;saveInterval(minutes);preview=null;update();return true;}catch(IllegalArgumentException e){intervalInput.custom.setError(e.getMessage());intervalInput.custom.requestFocus();fail(e.getMessage());}catch(Exception e){fail(Runner.safe(e));}return false;}
 private void planText(String t){planRows.removeAllViews();planView.setText(t);planView.setVisibility(t==null||t.isEmpty()?View.GONE:View.VISIBLE);}
 /** state: 0 not booked, 1 booked, 2 existing booking differs and needs an approved replacement. */
 private JSONArray planItems(List<Engine.Meal> p,List<Replacement.Conflict> cs)throws Exception{JSONArray a=new JSONArray();for(Engine.Meal m:p){boolean c=false;for(Replacement.Conflict x:cs)c|=x.target.key().equals(m.key());a.put(new JSONObject().put("day",m.day.toString()).put("meal",m.type).put("name",Engine.name(m.depot)).put("state",c?2:m.existingId>0?1:0));}return a;}
 /** One row per meal: label + restaurant, with a text status chip (never colour alone). Returns the number of rows drawn. */
 private int renderPlan(LinearLayout box,JSONArray items,LocalDate from){
  box.removeAllViews();int shown=0;String last="";DateTimeFormatter f=DateTimeFormatter.ofPattern("EEEE dd/MM",dateLocale());LocalDate today=Engine.today();
  for(int i=0;i<items.length();i++)try{
   JSONObject o=items.getJSONObject(i);LocalDate d=LocalDate.parse(o.getString("day"));int meal=o.getInt("meal"),state=o.optInt("state");if(meal<1||meal>3||(from!=null&&d.isBefore(from)))continue;
   String dayName=d.format(f)+(d.equals(today)?getString(R.string.render_plan_1):d.equals(today.plusDays(1))?getString(R.string.render_plan_2):"");
   if(!o.getString("day").equals(last)){last=o.getString("day");TextView h=text(dayName,14,ink);h.setTypeface(null,Typeface.BOLD);h.setPadding(0,dp(shown==0?6:14),0,dp(2));head(h);box.addView(h);}
   LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(0,dp(5),0,dp(5));r.addView(tile(MEAL_ICON[meal]),tileLp());LinearLayout names=panel();TextView a=text(meal(meal),12,muted);a.setPadding(0,0,0,0);TextView b=text(o.optString("name"),15,ink);b.setPadding(0,0,0,0);names.addView(a);names.addView(b);r.addView(names,new LinearLayout.LayoutParams(0,-2,1));
   String word=state==1?getString(R.string.compact_plan_1):state==2?getString(R.string.render_plan_3):getString(R.string.compact_plan_2);TextView chip=text(word,12,state==1?palette.successInk:state==2?palette.danger:palette.warningInk);chip.setTypeface(null,Typeface.BOLD);chip.setPadding(dp(10),dp(4),dp(10),dp(4));chip.setBackground(bg(state==1?palette.successBg:state==2?palette.dangerBg:palette.warningBg,10));LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(-2,-2);cl.setMarginStart(dp(8));r.addView(chip,cl);
   r.setFocusable(true);r.setContentDescription(dayName+getString(R.string.value_1)+meal(meal)+getString(R.string.value_1)+o.optString("name")+getString(R.string.value_1)+word);box.addView(r);shown++;
  }catch(Exception ignored){}
  return shown;
 }
 /** Today's three meals from the raw rows of a reading: a visible row gives state 1 and its cleaned name; otherwise state 0 with the configured fallback. */
 private JSONArray todayItems(JSONArray rows){JSONArray out=new JSONArray();try{String key=Engine.today().toString();JSONObject rule=null;try{rule=WeeklySchedule.rules(cfg).optJSONObject(Integer.toString(Engine.today().getDayOfWeek().getValue()));}catch(Exception ignored){}
  for(int m=1;m<=3;m++){if(mealSkipped(Engine.today(),m))continue;JSONObject item=new JSONObject().put("day",key).put("meal",m).put("state",0);String n="";
   for(int i=0;rows!=null&&i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null||!key.equals(r.optString("date_reserve")))continue;try{if(Engine.mealType(r)==m){item.put("state",1);n=Engine.clean(r.optString("depot_ar"));if(n.isEmpty())n=Engine.clean(r.optString("depot_fr"));}}catch(Exception ignored){}}
   if(n.isEmpty()){JSONObject ex=rule==null?null:rule.optJSONObject(Integer.toString(m));n=ex!=null?Engine.clean(ex.optString("name","")):"";if(n.isEmpty())n=Engine.clean(cfg.optString(AccountSettings.NAMES[m],""));}
   if(!n.isEmpty())item.put("name",n);out.put(item);}
 }catch(Exception ignored){}return out;}
 private void rememberPlan(JSONArray items,JSONObject account,JSONArray rows){try{JSONObject a=new JSONObject(account.toString());a.remove("password");vault.write(PLAN_CACHE,new JSONObject().put("at",System.currentTimeMillis()).put("items",items).put("today",todayItems(rows)).put("account",a));}catch(Exception ignored){}}
 private void forgetPlan(){try{vault.write(PLAN_CACHE,new JSONObject());}catch(Exception ignored){}}
 /** Home answers "are my next days booked?" from the last full confirmation or the last read-only preview, and says which one and when. */
 private void loadReview(){if(!AccountSettings.configured(cfg)){setStep(1);fail(getString(R.string.load_review_1));return;}setStep(2);preview=null;conflicts=Collections.emptyList();replaceButton.setVisibility(View.GONE);bookButton.setVisibility(View.GONE);activateButton.setVisibility(View.GONE);doneButton.setVisibility(View.GONE);planText(getString(R.string.load_review_2));reviewSummary.setText(getString(R.string.load_review_3)+every(vault.intervalMinutes()));JSONObject c=cfg;async(getString(R.string.load_review_4),()->Runner.preview(c),r->{if(r.plan==null)throw new Engine.Problem(getString(R.string.load_review_5));depots=r.depots;fillMeals();intervalInput.set(vault.intervalMinutes());preview=r.plan;conflicts=r.conflicts;previewAccount=new JSONObject(c.toString());previewDay=Engine.today();planText(conflicts.isEmpty()?"":getString(R.string.load_review_6)+Replacement.describe(conflicts));JSONArray items=planItems(preview,conflicts);renderPlan(planRows,items,null);rememberPlan(items,c,r.rows);boolean missing=false;for(Engine.Meal m:preview)missing|=m.existingId==0;bookButton.setText(missing?getString(R.string.screen_57):getString(R.string.load_review_7));bookButton.setVisibility(conflicts.isEmpty()?View.VISIBLE:View.GONE);replaceButton.setVisibility(conflicts.isEmpty()?View.GONE:View.VISIBLE);message(conflicts.isEmpty()?getString(R.string.load_review_8):getString(R.string.load_review_9));});}
 private void confirmReplacement(){if(!free())return;if(preview==null||conflicts.isEmpty()){fail(getString(R.string.confirm_replacement_1));return;}final JSONObject account;try{account=new JSONObject(previewAccount.toString());}catch(Exception e){fail(getString(R.string.confirm_replacement_2));return;}final LocalDate day=previewDay;final List<Replacement.Conflict> approved=new ArrayList<>(conflicts);TextView warning=text(Replacement.describe(approved)+getString(R.string.confirm_replacement_3),15,ink);warning.setPadding(dp(20),dp(12),dp(20),dp(12));ScrollView content=new ScrollView(this);content.addView(warning);new AlertDialog.Builder(this).setTitle(getString(R.string.confirm_replacement_4)).setView(content).setNegativeButton(getString(R.string.confirm_replacement_5),null).setPositiveButton(getString(R.string.confirm_replacement_6),(d,w)->{if(!free())return;preview=null;conflicts=Collections.emptyList();replaceButton.setVisibility(View.GONE);forgetPlan();async(getString(R.string.confirm_replacement_7),()->Runner.replace(this,account,day,approved,()->isDestroyed()),result->{update();planText(result);message(result);});}).show();}
 private void confirmBooking(){if(!free())return;try{JSONObject c=vault.account();if(preview==null||previewAccount==null||!AccountSettings.sameChoices(c,previewAccount)||!c.optString("student").equals(previewAccount.optString("student"))||!c.optString("password").equals(previewAccount.optString("password"))||!Engine.today().equals(previewDay)){fail(getString(R.string.confirm_replacement_1));return;}{forgetPlan();async(getString(R.string.confirm_booking_4),()->Runner.book(this,false,()->false),result->{preview=null;bookButton.setVisibility(View.GONE);activateButton.setVisibility(View.VISIBLE);doneButton.setVisibility(View.VISIBLE);update();planText("");message(result+getString(R.string.confirm_booking_5));});}}catch(Exception e){fail(Runner.safe(e));}}
 private void toggle(){if(!free())return;if(vault.enabled()){Automation.disengage(this,vault,false);update();message(getString(R.string.toggle_1));}else enable(false);}
 private boolean notifications(){NotificationManager n=getSystemService(NotificationManager.class);NotificationChannel c=n.getNotificationChannel(Automation.CHANNEL);return n.areNotificationsEnabled()&&(c==null||c.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
 private void enable(boolean finish){if(!free())return;if(!AccountSettings.configured(cfg)||!vault.tested()||vault.lastSuccess()==0||!Instant.ofEpochMilli(vault.lastSuccess()).atZone(Engine.ZONE).toLocalDate().equals(Engine.today())){openWizard(2);message(getString(R.string.enable_1));return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);message(getString(R.string.enable_2));return;}if(!notifications()){fail(getString(R.string.enable_3));return;}{vault.enable(true);Automation.start(this);Automation.enqueueCheck(this);update();if(finish)show(0);Automation.notify(this,getString(R.string.enable_8),10);message(getString(R.string.enabled_now,every(vault.intervalMinutes())));}}
