 private void editInterval(){LinearLayout content=panel();content.setLayoutDirection(dir);content.setPadding(dp(20),dp(10),dp(20),dp(10));IntervalInput local=new IntervalInput(content,vault.intervalMinutes());content.addView(text(getString(R.string.edit_interval_1),13,muted));AlertDialog d=new AlertDialog.Builder(this).setTitle(getString(R.string.screen_25)).setView(content).setNegativeButton(getString(R.string.common_cancel),null).setPositiveButton(getString(R.string.common_save),null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{int m=local.get();saveInterval(m);intervalInput.set(m);update();d.dismiss();message(getString(R.string.edit_interval_2));}catch(IllegalArgumentException e){local.custom.setError(e.getMessage());}catch(Exception e){fail(Runner.safe(e));}}));d.show();}
 private final class IntervalInput {
  final ChoiceField preset;final EditText custom;final TextView longWarning;
  IntervalInput(LinearLayout p,int minutes){
   preset=new ChoiceField(MainActivity.this,palette,getString(R.string.screen_25));List<String> labels=new ArrayList<>();for(int m:ScheduleConfig.PRESETS)labels.add(every(m));labels.add(getString(R.string.interval_1));preset.setItems(labels);p.addView(preset,new LinearLayout.LayoutParams(-1,-2));
   custom=input(p,getString(R.string.interval_2),InputType.TYPE_CLASS_NUMBER);longWarning=text(getString(R.string.interval_3),13,palette.warningInk);p.addView(longWarning);
   preset.setListener(n->{custom.setVisibility(n==ScheduleConfig.PRESETS.length?View.VISIBLE:View.GONE);warn();});
   custom.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){}public void afterTextChanged(android.text.Editable e){warn();}});set(minutes);
  }
  void warn(){int m=0;try{m=get();}catch(Exception ignored){}longWarning.setVisibility(m>=1440?View.VISIBLE:View.GONE);}
  void set(int m){int index=ScheduleConfig.PRESETS.length;for(int i=0;i<ScheduleConfig.PRESETS.length;i++)if(ScheduleConfig.PRESETS[i]==m)index=i;preset.setSelection(index);custom.setText(Integer.toString(m));custom.setVisibility(index==ScheduleConfig.PRESETS.length?View.VISIBLE:View.GONE);warn();}
  int get(){int i=preset.getSelectedItemPosition();return i<ScheduleConfig.PRESETS.length?ScheduleConfig.PRESETS[i]:ScheduleConfig.parse(custom.getText().toString());}
  void enabled(boolean b){preset.setEnabled(b);custom.setEnabled(b);custom.setAlpha(b?1f:.45f);}
 }
