 private void weeklyDay(int day){try{
  LinearLayout content=panel();content.setLayoutDirection(dir);content.setPadding(dp(20),dp(8),dp(20),dp(12));content.addView(text(getString(R.string.weekly_day_1),13,muted));
  ChoiceField[] pickers=new ChoiceField[4];int[] bases=new int[4],skips=new int[4];List<List<JSONObject>> lists=new ArrayList<>();lists.add(Collections.emptyList());JSONObject row=WeeklySchedule.rules(cfg).optJSONObject(Integer.toString(day));
  for(int meal=1;meal<=3;meal++){content.addView(text(meal(meal),15,ink));boolean baseSet=cfg.optLong(AccountSettings.IDS[meal],0)>0;List<JSONObject> options=AccountSettings.options(depots,meal);lists.add(options);List<String> names=new ArrayList<>();int skipPos=-1;if(baseSet){names.add(getString(R.string.weekly_day_2)+cfg.optString(AccountSettings.NAMES[meal],getString(R.string.weekly_day_3)));names.add(getString(R.string.weekly_skip));skipPos=1;}else names.add(getString(R.string.meal_unconfigured));int depotBase=names.size();int selected=0;JSONObject saved=row!=null?row.optJSONObject(Integer.toString(meal)):null;boolean savedSkip=saved!=null&&Boolean.TRUE.equals(saved.opt("skip"));for(int i=0;i<options.size();i++)names.add(Engine.name(options.get(i)));if(savedSkip){selected=skipPos>=0?skipPos:0;}else if(saved!=null){for(int i=0;i<options.size();i++)if(options.get(i).getLong("id")==saved.getLong("id"))selected=depotBase+i;if(selected==0){options.add(saved);names.add(getString(R.string.weekly_day_4)+saved.optString("name",getString(R.string.weekly_day_5)));selected=names.size()-1;}}ChoiceField spinner=new ChoiceField(this,palette,meal(meal));spinner.setItems(names);spinner.setSelection(selected);pickers[meal]=spinner;bases[meal]=depotBase;skips[meal]=skipPos;content.addView(spinner,new LinearLayout.LayoutParams(-1,-2));}
  TextView error=text("",13,palette.danger);content.addView(error);ScrollView scroller=new ScrollView(this);scroller.addView(content);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle(dayName(day)+getString(R.string.weekly_day_6)).setView(scroller).setNegativeButton(getString(R.string.common_cancel),null).setPositiveButton(getString(R.string.common_save),null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!free())return;try{JSONObject[] selected=new JSONObject[4];for(int meal=1;meal<=3;meal++){int pos=pickers[meal].getSelectedItemPosition();JSONObject chosen=null;if(pos>0){if(skips[meal]>=0&&pos==skips[meal])chosen=new JSONObject().put("skip",true);else {int i=pos-bases[meal];if(i>=0&&i<lists.get(meal).size())chosen=lists.get(meal).get(i);}}selected[meal]=chosen;}JSONObject next=WeeklySchedule.setDay(cfg,day,selected,depots);boolean changed=!AccountSettings.sameChoices(cfg,next);if(changed){Automation.disengage(this,vault,true);}vault.write("account",next);cfg=next;preview=null;update();dialog.dismiss();message(changed?getString(R.string.weekly_day_7):getString(R.string.weekly_day_8));}catch(Exception e){error.setText(Runner.safe(e));}}));dialog.show();
 }catch(Exception e){fail(Runner.safe(e));}}
