 private String describeJournal(JSONObject j){StringBuilder s=new StringBuilder();try{for(Iterator<String> it=j.keys();it.hasNext();){String k=it.next();if(s.length()>0)s.append("\n");String label=k;try{int cut=k.indexOf(':');int type=Integer.parseInt(k.substring(cut+1));label=LocalDate.parse(k.substring(0,cut)).format(DateTimeFormatter.ofPattern("EEEE dd/MM",dateLocale()))+" • "+meal(type);}catch(Exception ignored){}s.append(label);JSONObject e=j.optJSONObject(k);if(e!=null){if(e.optLong("at")>0)s.append(" (").append(stamp(e.optLong("at"))).append(")");if(!e.optString("reason").isEmpty())s.append(": ").append(e.optString("reason"));}}}catch(Exception ignored){}return s.toString();}
